<dialog class="help-image-viewer" id="help-image-viewer" aria-labelledby="help-image-title">
    <div class="help-image-toolbar"><h2 id="help-image-title">Screenshot</h2><button type="button" class="button secondary" data-help-image-close aria-label="Close screenshot">Close ×</button></div>
    <div class="help-image-stage" tabindex="0" role="region" aria-label="Screenshot detail"><img alt="" id="help-full-image"></div>
    <div class="help-image-footer"><button type="button" class="button secondary" data-help-image-zoom aria-pressed="false">Zoom in</button><a id="help-original-image" target="_blank" rel="noopener">Open full-size image in a new tab</a><span class="meta">Example screen · when zoomed, swipe or scroll across the image.</span></div>
</dialog>
